import{_ as a,c as o,o as t,ag as r}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"The IrregularChat Login","description":"","frontmatter":{"title":"The IrregularChat Login"},"headers":[],"relativePath":"general/the-irregularchat-login.md","filePath":"general/the-irregularchat-login.md","lastUpdated":null}'),i={name:"general/the-irregularchat-login.md"};function n(s,e,l,h,u,c){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="the-irregularchat-login" tabindex="-1">The IrregularChat Login <a class="header-anchor" href="#the-irregularchat-login" aria-label="Permalink to &quot;The IrregularChat Login&quot;">​</a></h1><h2 id="about-the-irregularchat-login" tabindex="-1">About The IrregularChat Login <a class="header-anchor" href="#about-the-irregularchat-login" aria-label="Permalink to &quot;About The IrregularChat Login&quot;">​</a></h2><blockquote><p>Using a self-hosted, open-source identity provider means prioritizing security and taking control of your most sensitive data. With Authentik, you no longer need to continually place your trust in a third-party service.</p></blockquote><p>The IrregularChat Login is powered by Authentik after we tested different options including local login, GitHub, KeyCloak, and Google. Regardless of which solution we chose, the decision to use an identity provider like Authentik was guided by the need for secure, flexible, and scalable solutions for our community. More insights can be found here: <a href="https://goauthentik.io/blog/2024-07-11-identity-self-hosted-or-in-the-cloud" target="_blank" rel="noreferrer">Authentik Blog Post on Identity Solutions</a>.</p><p>Issues with previous identity solutions:</p><ul><li><p><strong>Local Login</strong>: One login per account is inconvenient and less secure, especially when users don’t always have access to a password manager. Local logins also present more vulnerabilities and require constant patching. As our community grows, this solution is not sustainable.</p></li><li><p><strong>GitHub</strong>: Surprisingly, only a small portion of our members had GitHub accounts. While we attempted to use it as a forcing function, it became a barrier for simpler services like a wiki. GitHub also lacks automation and control for logins unless you opt for an expensive enterprise account.</p></li><li><p><strong>KeyCloak</strong>: Another self-hosted solution, but not as intuitive for managing the variety of services within our community.</p></li><li><p><strong>Google</strong>: While secure, Google raises privacy concerns, and depending on a large corporation for identity management wasn’t ideal for our self-hosted philosophy.</p></li></ul><h3 id="common-issues-and-questions" tabindex="-1">Common Issues and Questions <a class="header-anchor" href="#common-issues-and-questions" aria-label="Permalink to &quot;Common Issues and Questions&quot;">​</a></h3><h3 id="email-verification-on-first-login" tabindex="-1">Email Verification on First Login <a class="header-anchor" href="#email-verification-on-first-login" aria-label="Permalink to &quot;Email Verification on First Login&quot;">​</a></h3><p>If you see a message like this on first login:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>
<span class="line"><span>Check your Inbox for a verification email.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Likely this link has already been used to create an account so you need to requrest an account recovery link.</p><p>It is possible that you set your password and didn&#39;t realize that the password was acceptable so attempt to log in.</p><h3 id="forgot-my-password" tabindex="-1">Forgot My Password <a class="header-anchor" href="#forgot-my-password" aria-label="Permalink to &quot;Forgot My Password&quot;">​</a></h3><p><a href="https://sso.irregularchat.com/if/flow/default-recovery-flow/?next=%2F" target="_blank" rel="noreferrer">Reset IrregularChat Password</a></p><p>If you don’t have access to your email, message one of the Admins from the chat to retrieve your account. Please provide details such as when you joined and who added you.</p><h3 id="what-s-my-username" tabindex="-1">What&#39;s My Username? <a class="header-anchor" href="#what-s-my-username" aria-label="Permalink to &quot;What&#39;s My Username?&quot;">​</a></h3><p>You can log in using your email. However, if your account was set up by an admin and doesn’t have an email, message one of the Admins from the chat. Provide details like when you joined and who added you to help locate your account.</p><h3 id="how-do-i-make-an-account" tabindex="-1">How Do I Make an Account? <a class="header-anchor" href="#how-do-i-make-an-account" aria-label="Permalink to &quot;How Do I Make an Account?&quot;">​</a></h3><p>Do you have a .mil email? Use the <a href="https://sso.irregularchat.com/if/flow/default-enrollment-flow/?next=%2F" target="_blank" rel="noreferrer">Automated Account Registration</a>.</p><p>If not, message one of the Admins from the chat. You will need to provide bonafides and your email. Once verified, you will receive login credentials and information on services available with your account.</p><h3 id="how-to-invite-others-to-the-irregularchat" tabindex="-1">How to Invite Others to the IrregularChat <a class="header-anchor" href="#how-to-invite-others-to-the-irregularchat" aria-label="Permalink to &quot;How to Invite Others to the IrregularChat&quot;">​</a></h3><p>See the <a href="https://forum.irregularchat.com/t/community-links-to-chats-and-services/229#p-598-inviting-others-to-the-irregularchat-community-3" target="_blank" rel="noreferrer">Forum Post</a> while logged in</p>`,22)])])}const p=a(i,[["render",n]]);export{g as __pageData,p as default};
